/*
 TiTi Pet | 02 - DU LIEU MO PHONG TONG HOP
 Database: TiTiPetDB. Chi chay SAU database/TiTiPet.sql.
 Du lieu nhan vien/khach hang/hoa don/lich hen la GIA LAP de demo, khong phai thong tin that.
 Khong gan hau to kiem thu vao ma, ten san pham, ten khach hang, ghi chu nghiep vu.
 KHONG CHAY TREN DATABASE DANG CO DU LIEU: script chan neu bang da co dong.
 KHONG xoa, reset diem, thay doi ton kho hay ghi de hoa don hien co.
 Tai khoan duoc bam BCrypt; mat khau demo phai doi truoc khi trien khai that.
 Compatible with SQL Server 2012+ (GO belongs to SSMS/sqlcmd).
*/
USE [TiTiPetDB];
GO
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRY
    BEGIN TRANSACTION;
    IF DB_NAME() <> N'TiTiPetDB'
    THROW 51031, N'Sai database, phai la TiTiPetDB.', 1;
IF OBJECT_ID(N'dbo.HoaDon',N'U') IS NULL OR OBJECT_ID(N'dbo.DoiTra',N'U') IS NULL
    OR COL_LENGTH(N'dbo.DichVuSpa', N'thoiLuongPhut') IS NULL
    OR COL_LENGTH(N'dbo.SanPham', N'giaNhap') IS NULL
    THROW 51032, N'Chua co schema day du. Chay TiTiPet.sql truoc.', 1;
IF EXISTS (SELECT 1 FROM dbo.NhanVien) OR EXISTS (SELECT 1 FROM dbo.KhachHang)
    OR EXISTS (SELECT 1 FROM dbo.SanPham) OR EXISTS (SELECT 1 FROM dbo.HoaDon)
    OR EXISTS (SELECT 1 FROM dbo.LichHen)
    OR EXISTS (SELECT 1 FROM dbo.ThuCung)
    OR EXISTS (SELECT 1 FROM dbo.ThucAn)
    OR EXISTS (SELECT 1 FROM dbo.PhuKien)
    OR EXISTS (SELECT 1 FROM dbo.CaLamViec)
    OR EXISTS (SELECT 1 FROM dbo.PhieuKetCa)
    OR EXISTS (SELECT 1 FROM dbo.DoiTra)
    OR EXISTS (SELECT 1 FROM dbo.ChiTietHoaDon_SanPham)
    OR EXISTS (SELECT 1 FROM dbo.ChiTietHoaDon_DichVu)
    OR EXISTS (SELECT 1 FROM dbo.KhuyenMai)
    OR EXISTS (SELECT 1 FROM dbo.LichSuNhapKho)
    THROW 51033, N'Database da co du lieu. Hay backup va dung CSDL moi/trong; khong chen chong du lieu.', 1;
    DECLARE @NgayGoc DATETIME2(0) = CONVERT(DATETIME2(0),CONVERT(DATE,SYSDATETIME()));

