INSERT dbo.LichSuNhapKho(maSanPham, soLuongNhap, giaNhap, hanSuDungMoi, ngayNhap, ghiChu) VALUES ('SP0030', 41, 42000, NULL, DATEADD(MINUTE, 555, DATEADD(DAY,-26,@NgayGoc)), N'Nhập hàng định kỳ từ nhà cung cấp');
    -- Tinh nhat quan: tien sau thue tren chi tiet phai khop so tien phai thu cua hoa don.
    IF EXISTS (
        SELECT 1
        FROM dbo.HoaDon h
        OUTER APPLY (SELECT COALESCE(SUM(x.tienSauThue), 0) AS tong
                     FROM dbo.ChiTietHoaDon_SanPham x WHERE x.maHoaDon = h.maHoaDon) sp
        OUTER APPLY (SELECT COALESCE(SUM(x.tienSauThue), 0) AS tong
                     FROM dbo.ChiTietHoaDon_DichVu x WHERE x.maHoaDon = h.maHoaDon) dv
        WHERE sp.tong + dv.tong <> h.tienPhaiThu
    )
        THROW 51034, N'Chi tiet hoa don khong khop tong thanh toan; da rollback.', 1;
    IF EXISTS (
        SELECT 1 FROM dbo.ChiTietHoaDon_DichVu d
        JOIN dbo.HoaDon h ON h.maHoaDon = d.maHoaDon
        JOIN dbo.ThuCung tc ON tc.maThuCung = d.maThuCung
        WHERE tc.maKH <> h.maKH
    )
        THROW 51035, N'Thu cung tren hoa don khong thuoc dung khach hang; da rollback.', 1;
    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    THROW;
END CATCH;
GO

-- KIEM TRA: khong lay hash mat khau; so lieu de doi chieu TrangChu/ThongKe.
SELECT DB_NAME() AS tenDatabase,
       (SELECT COUNT(*) FROM dbo.NhanVien) AS soNhanVien,
       (SELECT COUNT(*) FROM dbo.KhachHang) AS soKhachHang,
       (SELECT COUNT(*) FROM dbo.ThuCung) AS soThuCung,
       (SELECT COUNT(*) FROM dbo.SanPham) AS soSanPham,
       (SELECT COUNT(*) FROM dbo.DichVuSpa) AS soDichVuSpa,
       (SELECT COUNT(*) FROM dbo.LichHen) AS soLichHen,
       (SELECT COUNT(*) FROM dbo.HoaDon) AS soHoaDon,
       (SELECT COUNT(*) FROM dbo.DoiTra) AS soDoiTra,
       (SELECT COUNT(*) FROM dbo.PhieuKetCa) AS soPhieuKetCa;
SELECT (SELECT COUNT(*) FROM dbo.LichHen WHERE thoiGianHen >= CONVERT(DATE,SYSDATETIME())
      AND thoiGianHen < DATEADD(DAY,1,CONVERT(DATE,SYSDATETIME())) AND trangThai<>'HUY') AS lichHenHomNay,
       (SELECT COUNT(*) FROM dbo.HoaDon WHERE ngayLap >= CONVERT(DATE,SYSDATETIME())
      AND ngayLap < DATEADD(DAY,1,CONVERT(DATE,SYSDATETIME())) AND trangThai='DA_THANH_TOAN') AS hoaDonHomNay,
       (SELECT COALESCE(SUM(tienPhaiThu),0) FROM dbo.HoaDon WHERE ngayLap >= CONVERT(DATE,SYSDATETIME())
      AND ngayLap < DATEADD(DAY,1,CONVERT(DATE,SYSDATETIME())) AND trangThai='DA_THANH_TOAN') AS doanhThuHomNay;
GO
